-- Seed seluruh kampung/kelurahan Kabupaten Jayawijaya.
-- Sumber: master wilayah SmartDesa (40 distrik, 332 kampung/kelurahan).
-- Aman dijalankan ulang: village_code adalah kunci unik; ID tenant yang sudah ada tidak diubah.
SET NAMES utf8mb4;
START TRANSACTION;

ON DUPLICATE KEY UPDATE
  province_code = VALUES(province_code),
  province_name = VALUES(province_name),
  regency_code = VALUES(regency_code),
  regency_name = VALUES(regency_name),
  district_code = VALUES(district_code),
  district_name = VALUES(district_name),
  village_code = VALUES(village_code),
  name = VALUES(name),
  status = VALUES(status);

COMMIT;
